/* Presentation-only hover details. Reads visible DOM text; never reads chart inputs or hidden formulas. */
(()=>{'use strict';let tip,timer,target,originalTitle,point={x:0,y:0};
const clean=s=>String(s||'').replace(/\s+/g,' ').trim();
function hide(){clearTimeout(timer);if(tip){tip.hidden=true;tip.textContent='';}if(target&&originalTitle!==null){target.setAttribute('title',originalTitle);originalTitle=null;}target=null;}
function candidate(node){if(!(node instanceof Element)||node.closest('dialog textarea,.preview-tools,#kp-hover-detail'))return null;return node.closest('[data-hover-detail],[title],td,th,.v38-name,.v38-degree,.v38-lords,.kp-planet-reference,.kp-house-reference,.home-table-cell,.kp-notation-marker');}
function information(node){if(!node||!node.getClientRects().length)return '';const explicit=clean(node.getAttribute('data-hover-detail')||node.getAttribute('title'));if(explicit)return explicit;const text=clean(node.textContent);const clipped=[node,...node.querySelectorAll('span,strong,small,div')].some(n=>n.scrollWidth>n.clientWidth+1||n.scrollHeight>n.clientHeight+1);if(clipped&&text)return text;return '';}
function position(){const width=tip.offsetWidth,height=tip.offsetHeight;tip.style.left=Math.max(8,Math.min(innerWidth-width-8,point.x+12))+'px';tip.style.top=Math.max(8,Math.min(innerHeight-height-8,point.y+14))+'px';}
function schedule(node){const text=information(node);if(!text)return;target=node;originalTitle=node.getAttribute('title');if(originalTitle!==null)node.removeAttribute('title');timer=setTimeout(()=>{if(target!==node||!node.isConnected)return;tip.textContent=text;tip.hidden=false;position();},180);}
function init(){if(document.getElementById('kp-hover-detail'))return;tip=document.createElement('div');tip.id='kp-hover-detail';tip.setAttribute('role','tooltip');tip.hidden=true;document.body.append(tip);const style=document.createElement('style');style.textContent='#kp-hover-detail{position:fixed;z-index:2147483000;max-width:min(340px,calc(100vw - 24px));padding:6px 9px;font:11px/1.45 Arial,"Nirmala UI",sans-serif;color:#304b64;background:rgba(245,249,253,.97);border:1px solid #d0dde8;border-radius:5px;box-shadow:0 2px 8px #23415f18;pointer-events:none;white-space:normal;overflow-wrap:anywhere}#kp-hover-detail[hidden]{display:none!important}body.dark-theme #kp-hover-detail{background:rgba(36,54,73,.97);color:#e0ebf5;border-color:#526a82}@media print{#kp-hover-detail{display:none!important}}';document.head.append(style);
 document.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;hide();const node=candidate(e.target);point={x:e.clientX,y:e.clientY};schedule(node);},{passive:true});document.addEventListener('pointerout',e=>{if(target&&(!e.relatedTarget||!target.contains(e.relatedTarget)))hide();},{passive:true});document.addEventListener('scroll',hide,{passive:true,capture:true});document.addEventListener('pointerdown',hide,{passive:true});window.addEventListener('blur',hide);document.addEventListener('keydown',hide);
}
window.KPHoverDetails=Object.freeze({hide});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();
